/** True on iOS devices that support Sign in with Apple. */
export function useAppleAvailable(): boolean {
  const [ok, setOk] = useState(false);
  useEffect(() => {
    let live = true;
    isAppleAvailable().then((v) => { if (live) setOk(v); });
    return () => { live = false; };
  }, []);
  return ok;
}

